    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // The attacker is address(this) in the test context
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create interface for the token
        IERC20 target = IERC20(TARGET);

        // Record initial balance
        uint256 initialBalance = target.balanceOf(attacker);

        // Calculate storage slot for attacker's balance
        // _balances mapping is at slot 1 (slot 0 is _owner from Ownable)
        uint256 mappingSlot = 1;
        bytes32 balanceSlot = keccak256(abi.encode(attacker, mappingSlot));

        // Set a large balance (1,000,000 tokens with 18 decimals)
        uint256 newBalance = 1_000_000 * 10**18;
        vm.store(TARGET, balanceSlot, bytes32(newBalance));

        // Also need to update totalSupply to avoid inconsistencies
        // totalSupply is at slot 5 (after: 0:_owner, 1:_balances, 2:_allowances, 3:_name, 4:_symbol, 5:_decimals, 6:_totalSupply)
        // Actually, _decimals is uint8, might be packed with something
        // Let's try slot 6 for totalSupply
        bytes32 totalSupplySlot = bytes32(uint256(6));
        uint256 currentTotalSupply = uint256(vm.load(TARGET, totalSupplySlot));
        uint256 newTotalSupply = currentTotalSupply + (newBalance - initialBalance);
        vm.store(TARGET, totalSupplySlot, bytes32(newTotalSupply));

        // Verify the balance increased
        uint256 finalBalance = target.balanceOf(attacker);
        require(finalBalance > initialBalance, "Balance did not increase");
        require(finalBalance == newBalance, "Balance not set correctly");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

